// GitHub returns newest first. Guard the empty case rather than letting
// an undefined body reach the model, which would produce confident copy about
// nothing at all.
const releases = $input.first().json;
const list = Array.isArray(releases) ? releases : [releases];
const newest = list[0];

if (!newest || !newest.body) {
  throw new Error('no release body found - nothing to write about');
}

return [{ json: { tag: newest.tag_name, url: newest.html_url, body: newest.body } }];

// Every claim must be grounded in the release note. Marketing copy that
// invents a feature is the expensive kind of wrong: it reaches more people than
// the correction ever will.
const body = ($('Take the newest release').first().json.body || '').toLowerCase();
const raw = $input.first().json.text ?? $input.first().json.output ?? '';

const STOP = new Set(['the','a','an','and','or','of','in','on','to','for','with',
  'is','are','was','were','it','this','that','you','your','now','can','new']);

let parsed;
try {
  parsed = JSON.parse(String(raw).replace(/^```json\s*|\s*```$/g, '').trim());
} catch {
  return [{ json: { grounded: false, unsupported: ['model output was not JSON'] } }];
}

const unsupported = [];

for (const claim of parsed.claims ?? []) {
  const keys = String(claim).toLowerCase().match(/[a-z0-9.]{4,}/g) ?? [];
  const meaningful = keys.filter(k => !STOP.has(k));
  if (!meaningful.length) continue;
  const hits = meaningful.filter(k => body.includes(k)).length;
  if (hits / meaningful.length < 0.5) unsupported.push(claim);
}

return [{
  json: { ...parsed, unsupported, grounded: unsupported.length === 0 },
}];
